Fixes: 8e04ce45a8db ("mptcp: fix MSG_PEEK stream corruption")
Signed-off-by: Li Xiasong <lixiasong1@huawei.com>
Reviewed-by: Matthieu Baerts (NGI0) <matttbe@kernel.org>
Link: https://patch.msgid.link/20260330120335.659027-1-lixiasong1@huawei.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
When MSG_PEEK is used with MSG_WAITALL, skbs are not removed from the receive queue due to peek semantics, causing sk_wait_data() to always find available data (the peeked but unremoved skbs) and return immediately without sleeping. This results in an infinite loop and soft lockup in mptcp_recvmsg().

Here is the patch:

 static int __mptcp_recvmsg_mskq(struct sock *sk, struct msghdr *msg,
 				size_t len, int flags, int copied_total,
 				struct scm_timestamping_internal *tss,
-				int *cmsg_flags)
+				int *cmsg_flags, struct sk_buff **last)
 {
 	struct mptcp_sock *msk = mptcp_sk(sk);
 	struct sk_buff *skb, *tmp;
 	int total_data_len = 0;
 	int copied = 0;

 	skb_queue_walk_safe(&sk->sk_receive_queue, skb, tmp) {
 		u32 delta, offset = MPTCP_SKB_CB(skb)->offset;
 		u32 data_len = skb->len - offset;
 		u32 count;
 		int err;

 		if (flags & MSG_PEEK) {
 			/* skip already peeked skbs */
 			if (total_data_len + data_len <= copied_total) {
 				total_data_len += data_len;
+				*last = skb;
 				continue;
 			}

 			/* skip the already peeked data in the current skb */
 			delta = copied_total - total_data_len;
 			offset += delta;
 			data_len -= delta;
 		}

 		count = min_t(size_t, len - copied, data_len);
 		if (!(flags & MSG_TRUNC)) {
 			err = skb_copy_datagram_msg(skb, offset, msg, count);
 			if (unlikely(err < 0)) {
 				if (!copied)
 					return err;
 				break;
 			}
 		}

 		if (MPTCP_SKB_CB(skb)->has_rxtstamp) {
 			tcp_update_recv_tstamps(skb, tss);
 			*cmsg_flags |= MPTCP_CMSG_TS;
 		}

 		copied += count;

 		if (!(flags & MSG_PEEK)) {
 			msk->bytes_consumed += count;
 			if (count < data_len) {
 				MPTCP_SKB_CB(skb)->offset += count;
 				MPTCP_SKB_CB(skb)->map_seq += count;
 				break;
 			}

 			mptcp_eat_recv_skb(sk, skb);
+		} else {
+			*last = skb;
 		}

 		if (copied >= len)
 			break;
 	}

 	mptcp_rcv_space_adjust(msk, copied);
 	return copied;
 }


 static int mptcp_recvmsg(struct sock *sk, struct msghdr *msg, size_t len,
 			 int flags, int *addr_len)
 {
 	struct mptcp_sock *msk = mptcp_sk(sk);
 	struct scm_timestamping_internal tss;
 	int copied = 0, cmsg_flags = 0;
 	int target;
 	long timeo;

 	/* MSG_ERRQUEUE is really a no-op till we support IP_RECVERR */
 	if (unlikely(flags & MSG_ERRQUEUE))
 		return inet_recv_error(sk, msg, len, addr_len);

 	lock_sock(sk);
 	if (unlikely(sk->sk_state == TCP_LISTEN)) {
 		copied = -ENOTCONN;
 		goto out_err;
 	}

 	mptcp_rps_record_subflows(msk);

 	timeo = sock_rcvtimeo(sk, flags & MSG_DONTWAIT);

 	len = min_t(size_t, len, INT_MAX);
 	target = sock_rcvlowat(sk, flags & MSG_WAITALL, len);

 	if (unlikely(msk->recvmsg_inq))
 		cmsg_flags = MPTCP_CMSG_INQ;

 	while (copied < len) {
+		struct sk_buff *last = NULL;
 		int err, bytes_read;

 		bytes_read = __mptcp_recvmsg_mskq(sk, msg, len - copied, flags,
-						  copied, &tss, &cmsg_flags);
+						  copied, &tss, &cmsg_flags,
+						  &last);
 		if (unlikely(bytes_read < 0)) {
 			if (!copied)
 				copied = bytes_read;
 			goto out_err;
 		}

 		copied += bytes_read;

 		if (!list_empty(&msk->backlog_list) && mptcp_move_skbs(sk))
 			continue;

 		/* only the MPTCP socket status is relevant here. The exit
 		 * conditions mirror closely tcp_recvmsg()
 		 */
 		if (copied >= target)
 			break;

 		if (copied) {
 			if (sk->sk_err ||
 			    sk->sk_state == TCP_CLOSE ||
 			    (sk->sk_shutdown & RCV_SHUTDOWN) ||
 			    !timeo ||
 			    signal_pending(current))
 				break;
 		} else {
 			if (sk->sk_err) {
 				copied = sock_error(sk);
 				break;
 			}

 			if (sk->sk_shutdown & RCV_SHUTDOWN)
 				break;

 			if (sk->sk_state == TCP_CLOSE) {
 				copied = -ENOTCONN;
 				break;
 			}

 			if (!timeo) {
 				copied = -EAGAIN;
 				break;
 			}

 			if (signal_pending(current)) {
 				copied = sock_intr_errno(timeo);
 				break;
 			}
 		}

 		pr_debug("block timeout %ld\n", timeo);
 		mptcp_cleanup_rbuf(msk, copied);
-		err = sk_wait_data(sk, &timeo, NULL);
+		err = sk_wait_data(sk, &timeo, last);
 		if (err < 0) {
 			err = copied ? : err;
 			goto out_err;
 		}
 	}

 	mptcp_cleanup_rbuf(msk, copied);

 out_err:
 	if (cmsg_flags && copied >= 0) {
 		if (cmsg_flags & MPTCP_CMSG_TS)
 			tcp_recv_timestamp(msg, sk, &tss);

 		if (cmsg_flags & MPTCP_CMSG_INQ) {
 			unsigned int inq = mptcp_inq_hint(sk);

 			put_cmsg(msg, SOL_TCP, TCP_CM_INQ, sizeof(inq), &inq);
 		}
 	}

 	pr_debug("msk=%p rx queue empty=%d copied=%d\n",
 		 msk, skb_queue_empty(&sk->sk_receive_queue), copied);

 	release_sock(sk);
 	return copied;
 }



